sys_script_client.script:
function onLoad() {
   //Type appropriate comment here, and begin script below
    var year = new Date().getFullYear();
    for (var i = 0; i <= 10; i++) {
        var choices = year + i;
        g_form.addOption('u_year', choices, choices);
    }

    var currentMonth = new Date().getMonth();
    var allMonths = {
        0: 'u_january',
        1: 'u_february',
        2: 'u_march',
        3: 'u_april',
        4: 'u_may',
        5: 'u_june',
        6: 'u_july',
        7: 'u_august',
        8: 'u_september',
        9: 'u_october',
        10: 'u_november',
        11: 'u_december'
    }
    for (var month in allMonths) {
        if (parseInt(month) < currentMonth) {
            g_form.setReadOnly(allMonths[month], true);
        }
    }

}
